// Safe retrieval helper with intelligent program & branch fallback
export function getCurriculum(
  batchId: string,
  branchId: string,
  semester: number,
  programId: ProgramType = "btech"
): SRBSubject[] {
  if (programId === "mbatech") {
    const batchData = MBA_TECH_DATABASE[batchId] || MBA_TECH_DATABASE["2026"];
    // direct branch lookup or closest MBA Tech branch
    let branchData = batchData[branchId];
    if (!branchData) {
      if (branchId === "cs" || branchId === "cseds" || branchId === "cyber" || branchId === "csbs") {
        branchData = batchData["ce"] || batchData["it"];
      } else if (branchId === "aiml" || branchId === "aids") {
        branchData = batchData["ai"] || batchData["ds"] || batchData["ce"];
      } else {
        branchData = batchData["it"] || batchData["ce"];
      }
    }
    const semCourses = branchData?.[semester];
    if (semCourses && semCourses.length > 0) return semCourses;
    const fallbackBatch = MBA_TECH_DATABASE[batchId]?.["ce"] || MBA_TECH_DATABASE["2026"]["ce"];
    if (fallbackBatch?.[semester] && fallbackBatch[semester].length > 0) return fallbackBatch[semester];
    // fallback to B.Tech branch if sparse
    const btechBatch = SRB_DATABASE[batchId] || SRB_DATABASE["2026"];
    return btechBatch?.[branchId]?.[semester] || btechBatch?.["ce"]?.[semester] || [];
  }

  if (programId === "diploma") {
    const batchData = DIPLOMA_DATABASE[batchId] || DIPLOMA_DATABASE["2026"];
    const branchData = batchData[branchId] || batchData["ce"] || batchData["it"] || batchData["cseds"];
    const semCourses = branchData?.[semester];
    if (semCourses && semCourses.length > 0) return semCourses;
    const fallbackBatch = DIPLOMA_DATABASE[batchId]?.["ce"] || DIPLOMA_DATABASE["2026"]["ce"];
    return fallbackBatch?.[semester] || [];
  }

  // B.Tech
  const batchData = SRB_DATABASE[batchId] || SRB_DATABASE["2026"];
  const branchData = batchData[branchId] || batchData["ce"] || batchData["it"];
  const semCourses = branchData?.[semester];

  if (semCourses && semCourses.length > 0) {
    return semCourses;
  }

  // Graceful fallback to CE if this specific branch semester is sparse
  const fallbackBatch = SRB_DATABASE[batchId]?.["ce"] || SRB_DATABASE["2026"]["ce"];
  return fallbackBatch?.[semester] || [];
}

